<?php
require_once __DIR__ . '/config/customer-auth.php';
require_once __DIR__ . '/includes/notifications.php';
if (!customer_logged_in()) { header('Location: ' . page_url('login.php?redirect=notifikasi-member.php')); exit; }
$pdo = db();
if (!$pdo) die('Database belum terhubung.');
$user = customer_user(); $cid = (int)$user['id'];
notifications_ensure_tables($pdo);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!customer_verify_csrf($_POST['csrf'] ?? '')) { $error = 'Sesi tidak valid. Silakan muat ulang halaman.'; }
    else { member_notification_mark_read($pdo, $cid, !empty($_POST['notification_id']) ? (int)$_POST['notification_id'] : null); header('Location: ' . page_url('notifikasi-member.php')); exit; }
}
$items = member_notifications($pdo, $cid, 100);
function nm_e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function nm_icon($type){ return match($type){ 'promo'=>'bi-ticket-perforated','voucher'=>'bi-ticket-detailed','reward'=>'bi-gift','points'=>'bi-stars','bonus'=>'bi-trophy','order'=>'bi-bag-check',default=>'bi-bell' }; }
function nm_date($v){ return date('d M Y, H:i', strtotime($v)); }
